create extension if not exists postgis with schema extensions;
create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade,name text,avatar_url text,timezone text default 'UTC',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.memory_pairs(id uuid primary key default gen_random_uuid(),user_1_id uuid not null references public.profiles(id) on delete cascade,user_2_id uuid references public.profiles(id) on delete cascade,name text not null default 'Our memories',consent_user_1 boolean not null default false,consent_user_2 boolean not null default false,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),check(user_1_id<>user_2_id));
create table if not exists public.google_connections(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.profiles(id) on delete cascade,provider text not null default 'google_photos',provider_subject text,encrypted_refresh_token text,scopes text[] not null default '{}',status text not null default 'active',last_synced_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(user_id,provider));
create table if not exists public.memories(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.profiles(id) on delete cascade,external_id text not null,media_type text not null,filename text,captured_at timestamptz,location extensions.geography(point,4326),location_name text,city text,country text,location_accuracy_meters double precision,metadata jsonb not null default '{}',created_at timestamptz not null default now(),unique(user_id,external_id));
create index if not exists memories_user_captured_idx on public.memories(user_id,captured_at desc);create index if not exists memories_location_idx on public.memories using gist(location);
create table if not exists public.events(id uuid primary key default gen_random_uuid(),memory_pair_id uuid not null references public.memory_pairs(id) on delete cascade,title text not null,description text,start_time timestamptz,end_time timestamptz,location extensions.geography(point,4326),location_name text,event_type text not null default 'unknown',confidence double precision not null default .5,source text not null default 'inference',created_at timestamptz not null default now());
create table if not exists public.event_memories(event_id uuid not null references public.events(id) on delete cascade,memory_id uuid not null references public.memories(id) on delete cascade,primary key(event_id,memory_id));
create table if not exists public.shared_timeline(id uuid primary key default gen_random_uuid(),memory_pair_id uuid not null references public.memory_pairs(id) on delete cascade,timeline_date date not null,relationship_state text not null check(relationship_state in('TOGETHER','NEARBY','APART','UNKNOWN')),distance_km double precision,confidence double precision not null default .5,event_id uuid references public.events(id) on delete set null,evidence jsonb not null default '{}',created_at timestamptz not null default now(),unique(memory_pair_id,timeline_date));
alter table public.profiles enable row level security;alter table public.memory_pairs enable row level security;alter table public.google_connections enable row level security;alter table public.memories enable row level security;alter table public.events enable row level security;alter table public.event_memories enable row level security;alter table public.shared_timeline enable row level security;
create policy "profiles own" on public.profiles for all using(id=auth.uid()) with check(id=auth.uid());
create policy "pairs members read" on public.memory_pairs for select using(user_1_id=auth.uid() or user_2_id=auth.uid());
create policy "pairs member insert" on public.memory_pairs for insert with check(user_1_id=auth.uid() or user_2_id=auth.uid());
create policy "pairs members update" on public.memory_pairs for update using(user_1_id=auth.uid() or user_2_id=auth.uid());
create policy "connections own" on public.google_connections for all using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy "memories own" on public.memories for all using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy "events members" on public.events for select using(exists(select 1 from public.memory_pairs p where p.id=memory_pair_id and(p.user_1_id=auth.uid() or p.user_2_id=auth.uid())));
create policy "event memories members" on public.event_memories for select using(exists(select 1 from public.events e join public.memory_pairs p on p.id=e.memory_pair_id where e.id=event_id and(p.user_1_id=auth.uid() or p.user_2_id=auth.uid())));
create policy "timeline members" on public.shared_timeline for select using(exists(select 1 from public.memory_pairs p where p.id=memory_pair_id and(p.user_1_id=auth.uid() or p.user_2_id=auth.uid())));
alter table public.google_connections add column if not exists encrypted_access_token text;
alter table public.google_connections add column if not exists access_token_expires_at timestamptz;
